@Composable
fun MedTimingNavGraph(navController: NavHostController = rememberNavController()) {
    val currentRoute = navController.currentBackStackEntryAsState().value?.destination?.route

    Scaffold(
        bottomBar = {
            if (currentRoute != Routes.SETTINGS) {
                NavigationBar {
                    bottomNavTabs.forEach { tab ->
                        NavigationBarItem(
                            selected = currentRoute == tab.route,
                            onClick = {
                                navController.navigate(tab.route) {
                                    popUpTo(Routes.DAILY_LIST) { saveState = true }
                                    launchSingleTop = true
                                    restoreState = true
                                }
                            },
                            icon = { Icon(tab.icon, contentDescription = stringResource(tab.labelRes)) },
                            label = { Text(stringResource(tab.labelRes)) },
                        )
                    }
                }
            }
        },
    ) { innerPadding ->
        NavHost(
            navController = navController,
            startDestination = Routes.DAILY_LIST,
            modifier = Modifier.padding(bottom = innerPadding.calculateBottomPadding()),
        ) {
            composable(Routes.DAILY_LIST) {
                DailyListScreen(
                    onSettings = { navController.navigate(Routes.SETTINGS) },
                )
            }
            composable(Routes.MANAGE_PROFILES) {
                ManageProfilesScreen(
                    onSettings = { navController.navigate(Routes.SETTINGS) },
                )
            }
            composable(Routes.MANAGE_MEDICATIONS) {
                ManageMedicationsScreen(
                    onSettings = { navController.navigate(Routes.SETTINGS) },
                )
            }
            composable(Routes.SETTINGS) { SettingsScreen() }
        }
    }
}
